#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stdlib.h>  /* Added for malloc/free */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "correlation.h"

/* I-tile size for correlation: TILE_I rows of data_t (each N doubles)
 * are kept in L2 cache while streaming through all j-rows. This reduces
 * main-memory traffic by ~TILE_I for the dominant O(M^2*N) term.
 * For N=2600: 8*2600*8 bytes = ~166KB, fitting in typical 256KB+ L2. */
#define TILE_I 8


/* Array initialization. */
static
void init_array (int m,
		 int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)N;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = (DATA_TYPE)(i*j)/M + i;

}


