   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(corr,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("corr");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);


#pragma scop

  /* ================================================================
   * PHASE 1: Compute column means
   * Optimization: Loop interchange — original had outer j, inner i
   * causing stride-M (column-major) access. Swapped to outer i,
   * inner j for sequential row-major access to data[i][j].
   * ================================================================ */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      mean[j] += data[i][j];

  for (j = 0; j < _PB_M; j++)
    mean[j] /= float_n;


  /* ================================================================
   * PHASE 2: Compute column standard deviations
   * Same loop interchange optimization for row-major data access.
   * ================================================================ */
  for (j = 0; j < _PB_M; j++)
    stddev[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++) {
      DATA_TYPE d = data[i][j] - mean[j];
      stddev[j] += d * d;
    }

  for (j = 0; j < _PB_M; j++) {
    stddev[j] /= float_n;
    stddev[j] = SQRT_FUN(stddev[j]);
    /* The following in an inelegant but usual way to handle
       near-zero std. dev. values, which below would cause a zero-
       divide. */
    stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
  }

  /* ================================================================
   * Precompute inverse normalization factors to replace division
   * with multiplication in the inner loop:
   *   factor[j] = 1.0 / (sqrt(float_n) * stddev[j])
   * Stored in stddev[] (original values no longer needed).
   * ================================================================ */
  {
    DATA_TYPE inv_sqrt_n = SCALAR_VAL(1.0) / SQRT_FUN(float_n);
    for (j = 0; j < _PB_M; j++)
      stddev[j] = inv_sqrt_n / stddev[j];
  }

  /* ================================================================
   * PHASES 3+4: Fused normalize-transpose, then tiled correlation
   *
   * Step A: Build transposed normalized matrix in one pass:
   *   data_t[col*N + row] = (data[row][col] - mean[col]) * factor[col]
   * This saves a separate normalize pass over data[].
   * The transpose converts the correlation's column-wise access
   * (stride M) into sequential access (stride 1).
   *
   * Step B: I-tiled correlation with register blocking.
   * TILE_I i-rows stay in L2 cache while streaming all j-rows,
   * reducing DRAM traffic ~TILE_I×. Each rj[k] is reused for
   * TILE_I multiply-accumulates per k-step.
   * ================================================================ */
  {
    /* Allocate transposed normalized data: M rows × N columns */
    DATA_TYPE * restrict data_t = (DATA_TYPE *)malloc(
        (size_t)_PB_M * (size_t)_PB_N * sizeof(DATA_TYPE));

    /* --- Step A: Cache-blocked normalize-and-transpose ---
     * Tile size TB ensures both the source tile in data[] and the
     * destination tile in data_t[] fit in L1 cache together. */
    {
      const int TB = 32;
      int ii, jj;
      for (ii = 0; ii < _PB_N; ii += TB) {
        int i_end = (ii + TB < _PB_N) ? (ii + TB) : _PB_N;
        for (jj = 0; jj < _PB_M; jj += TB) {
          int j_end = (jj + TB < _PB_M) ? (jj + TB) : _PB_M;
          for (i = ii; i < i_end; i++)
            for (j = jj; j < j_end; j++)
              data_t[(size_t)j * _PB_N + i] =
                  (data[i][j] - mean[j]) * stddev[j];
        }
      }
    }

    /* --- Step B: I-tiled correlation matrix computation ---
     *
     * For each tile of TILE_I consecutive i-rows:
     *   - The tile's rows stay in L2 across all j iterations.
     *   - Each j loads one row_j from memory, shared across TILE_I
     *     dot products.
     *   - Inner k-loop: 1 load (rj) + TILE_I loads (ri's) feeding
     *     TILE_I FMAs — near-optimal for x86 2-load/2-FMA ports.
     *
     * Unused tile slots (when num_i < TILE_I) alias ri0; their
     * dot products are computed but discarded, avoiding branches
     * in the performance-critical inner loop.
     * ============================================================ */

    /* Set all diagonal elements */
    for (i = 0; i < _PB_M; i++)
      corr[i][i] = SCALAR_VAL(1.0);

    for (int ii = 0; ii < _PB_M - 1; ii += TILE_I) {
      int i_limit = ii + TILE_I;
      if (i_limit > _PB_M) i_limit = _PB_M;
      int num_i = i_limit - ii;

      /* Row pointers for this tile; fallback to ri0 if out of range */
      const DATA_TYPE *ri0 = &data_t[(size_t)(ii)   * _PB_N];
      const DATA_TYPE *ri1 = (num_i>1)?&data_t[(size_t)(ii+1)*_PB_N]:ri0;
      const DATA_TYPE *ri2 = (num_i>2)?&data_t[(size_t)(ii+2)*_PB_N]:ri0;
      const DATA_TYPE *ri3 = (num_i>3)?&data_t[(size_t)(ii+3)*_PB_N]:ri0;
      const DATA_TYPE *ri4 = (num_i>4)?&data_t[(size_t)(ii+4)*_PB_N]:ri0;
      const DATA_TYPE *ri5 = (num_i>5)?&data_t[(size_t)(ii+5)*_PB_N]:ri0;
      const DATA_TYPE *ri6 = (num_i>6)?&data_t[(size_t)(ii+6)*_PB_N]:ri0;
      const DATA_TYPE *ri7 = (num_i>7)?&data_t[(size_t)(ii+7)*_PB_N]:ri0;

      for (j = ii + 1; j < _PB_M; j++) {
        const DATA_TYPE *rj = &data_t[(size_t)j * _PB_N];

        /* TILE_I dot products sharing each rj[k] load */
        DATA_TYPE s0 = SCALAR_VAL(0.0), s1 = SCALAR_VAL(0.0);
        DATA_TYPE s2 = SCALAR_VAL(0.0), s3 = SCALAR_VAL(0.0);
        DATA_TYPE s4 = SCALAR_VAL(0.0), s5 = SCALAR_VAL(0.0);
        DATA_TYPE s6 = SCALAR_VAL(0.0), s7 = SCALAR_VAL(0.0);

        for (k = 0; k < _PB_N; k++) {
          DATA_TYPE vj = rj[k];
          s0 += ri0[k] * vj;
          s1 += ri1[k] * vj;
          s2 += ri2[k] * vj;
          s3 += ri3[k] * vj;
          s4 += ri4[k] * vj;
          s5 += ri5[k] * vj;
          s6 += ri6[k] * vj;
          s7 += ri7[k] * vj;
        }

        /* Store valid pairs where ii+idx < j */
        int valid_i = ((j - ii) < num_i) ? (j - ii) : num_i;

                            corr[ii  ][j]=s0; corr[j][ii  ]=s0;
        if (valid_i > 1) {  corr[ii+1][j]=s1; corr[j][ii+1]=s1; }
        if (valid_i > 2) {  corr[ii+2][j]=s2; corr[j][ii+2]=s2; }
        if (valid_i > 3) {  corr[ii+3][j]=s3; corr[j][ii+3]=s3; }
        if (valid_i > 4) {  corr[ii+4][j]=s4; corr[j][ii+4]=s4; }
        if (valid_i > 5) {  corr[ii+5][j]=s5; corr[j][ii+5]=s5; }
        if (valid_i > 6) {  corr[ii+6][j]=s6; corr[j][ii+6]=s6; }
        if (valid_i > 7) {  corr[ii+7][j]=s7; corr[j][ii+7]=s7; }
      }
    }

    free(data_t);
  }

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(corr,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
