static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);


#pragma scop

  /*
   * Optimization: Row-major traversal for column-mean computation.
   * Original iterates j (outer), i (inner) over data[i][j], causing
   * stride-M access. Swapping to i-outer, j-inner gives stride-1
   * access along each row of data.
   */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      mean[j] += data[i][j];
  for (j = 0; j < _PB_M; j++)
    mean[j] /= float_n;

  /*
   * Optimization: Row-major traversal for stddev computation.
   * Same rationale as above — keeps data access stride-1.
   */
  for (j = 0; j < _PB_M; j++)
    stddev[j] = SCALAR_VAL(0.0);
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++) {
      DATA_TYPE d = data[i][j] - mean[j];
      stddev[j] += d * d;
    }

  /*
   * Optimization: Precompute combined scale factor = 1/(sqrt(n)*stddev[j]).
   * The normalization originally divides by (sqrt(n)*stddev[j]) in the hot
   * inner loop. We precompute the reciprocal so the inner loop uses a
   * cheaper multiplication. We reuse the stddev[] array to store it.
   */
  {
    DATA_TYPE inv_sqrt_n = SCALAR_VAL(1.0) / SQRT_FUN(float_n);
    for (j = 0; j < _PB_M; j++) {
      stddev[j] /= float_n;
      stddev[j] = SQRT_FUN(stddev[j]);
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
      /* Repurpose stddev[j] as the combined scale factor */
      stddev[j] = inv_sqrt_n / stddev[j];
    }
  }

  /* Center and reduce column vectors using precomputed scale (multiply
     instead of divide). Row-major traversal for stride-1 access. */
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] = (data[i][j] - mean[j]) * stddev[j];

  /*
   * Optimization: Transpose data[N][M] -> data_t[M][N] for the
   * correlation computation.
   *
   * Correlation computes corr[i][j] = sum_k data[k][i]*data[k][j],
   * which accesses columns of data (stride M per k-step) — very poor
   * for cache and SIMD. After transposing:
   *   corr[i][j] = sum_k data_t[i][k] * data_t[j][k]
   * Both operands now have stride-1 access, enabling full SIMD
   * vectorization (AVX/AVX-512) of the inner dot-product loop.
   *
   * A tiled transpose (32x32 blocks) ensures both source and
   * destination blocks fit in L1 cache simultaneously.
   */
  DATA_TYPE (* restrict data_t)[N] =
      (DATA_TYPE (*)[N])malloc((size_t)M * (size_t)N * sizeof(DATA_TYPE));
  {
    enum { TILE = 32 };
    int ii, jj;
    for (ii = 0; ii < _PB_N; ii += TILE) {
      int ilim = (ii + TILE < _PB_N) ? ii + TILE : _PB_N;
      for (jj = 0; jj < _PB_M; jj += TILE) {
        int jlim = (jj + TILE < _PB_M) ? jj + TILE : _PB_M;
        for (i = ii; i < ilim; i++)
          for (j = jj; j < jlim; j++)
            data_t[j][i] = data[i][j];
      }
    }
  }

  /* Calculate the m * m correlation matrix using transposed data. */

  /* Set diagonal entries to 1.0 */
  for (i = 0; i < _PB_M; i++)
    corr[i][i] = SCALAR_VAL(1.0);

  /*
   * Optimization: Unroll the j-loop by 4 so that data_t[i][] (one
   * full row of length N) is loaded into cache once and reused across
   * 4 independent dot products. This cuts loads of data_t[i] by ~4x,
   * reducing memory bandwidth pressure. The restrict-qualified row
   * pointers help the compiler prove no aliasing, enabling aggressive
   * SIMD code generation for the inner k-loop.
   */
  for (i = 0; i < _PB_M - 1; i++) {
    const DATA_TYPE * restrict ri = data_t[i];

    /* Process 4 j-values at a time */
    j = i + 1;
    for (; j + 3 < _PB_M; j += 4) {
      const DATA_TYPE * restrict rj0 = data_t[j];
      const DATA_TYPE * restrict rj1 = data_t[j + 1];
      const DATA_TYPE * restrict rj2 = data_t[j + 2];
      const DATA_TYPE * restrict rj3 = data_t[j + 3];
      DATA_TYPE s0 = SCALAR_VAL(0.0);
      DATA_TYPE s1 = SCALAR_VAL(0.0);
      DATA_TYPE s2 = SCALAR_VAL(0.0);
      DATA_TYPE s3 = SCALAR_VAL(0.0);
      for (k = 0; k < _PB_N; k++) {
        DATA_TYPE d = ri[k];
        s0 += d * rj0[k];
        s1 += d * rj1[k];
        s2 += d * rj2[k];
        s3 += d * rj3[k];
      }
      corr[i][j]     = s0;  corr[j][i]     = s0;
      corr[i][j + 1] = s1;  corr[j + 1][i] = s1;
      corr[i][j + 2] = s2;  corr[j + 2][i] = s2;
      corr[i][j + 3] = s3;  corr[j + 3][i] = s3;
    }
    /* Handle remaining j values (0 to 3 leftover) */
    for (; j < _PB_M; j++) {
      const DATA_TYPE * restrict rj = data_t[j];
      DATA_TYPE s = SCALAR_VAL(0.0);
      for (k = 0; k < _PB_N; k++)
        s += ri[k] * rj[k];
      corr[i][j] = s;
      corr[j][i] = s;
    }
  }

  free(data_t);

#pragma endscop

}


