static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);


#pragma scop

  /* =================================================================
   * Optimization 1: Compute mean using row-major traversal.
   * Original code uses j-outer/i-inner (column-major), causing
   * strided access on data[i][j] with stride M elements per step.
   * Switching to i-outer/j-inner gives sequential row access,
   * dramatically improving spatial locality and prefetcher use.
   * mean[] and data rows both accessed sequentially in the inner loop.
   * ================================================================= */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      mean[j] += data[i][j];
  for (j = 0; j < _PB_M; j++)
    mean[j] /= float_n;

