  for (j = 0; j < _PB_M; j++)
    stddev[j] = SCALAR_VAL(0.0);
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++) {
      DATA_TYPE diff = data[i][j] - mean[j];
      stddev[j] += diff * diff;
    }
