   * Optimization 2: Create transposed normalized data array.
   * data_t[col][obs] = normalized data[obs][col].
   *
   * This is the key optimization: transposing makes both operands
   * of the correlation dot product sequential in memory, enabling:
   *  - Pure register accumulation (no array store in inner loop)
   *  - Efficient SIMD vectorization without gather instructions
   *  - Better prefetcher utilization (two sequential streams)
   *
   * The original inner loop (j-inner after restructuring) requires
   * a load+FMA+store per vector; the transposed version (k-inner)
   * needs only load+FMA, storing once at the very end. This removes
   * the store-port bottleneck, roughly doubling throughput.
   *
   * Also precompute reciprocal scale factor to replace division
   * with multiplication during normalization.
   * ================================================================= */

  DATA_TYPE inv_sqrt_n = SCALAR_VAL(1.0) / SQRT_FUN(float_n);

  /* Allocate M rows x N columns for transposed normalized data */
  DATA_TYPE (*data_t)[N] = (DATA_TYPE (*)[N])malloc(
      (size_t)M * (size_t)N * sizeof(DATA_TYPE));

  /* Build data_t and simultaneously compute scale factors.
   * j-outer gives sequential writes to data_t rows.
   * Reuse stddev[] to store the combined scale factor. */
  for (j = 0; j < _PB_M; j++) {
    DATA_TYPE mj = mean[j];
    DATA_TYPE sj = inv_sqrt_n / stddev[j];
    stddev[j] = sj;  /* Reuse stddev as precomputed scale factor */
    for (i = 0; i < _PB_N; i++)
      data_t[j][i] = (data[i][j] - mj) * sj;
  }

  /* Center and reduce data in-place (preserves original semantics).
   * Uses precomputed scale factor (multiplication) instead of
   * the original division by sqrt(n)*stddev[j]. */
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] = (data[i][j] - mean[j]) * stddev[j];

  /* =================================================================
   * Optimization 3: Correlation via register-blocked dot products.
   *
   * Process 4 column-pairs (j values) at a time, sharing the load
   * of data_t[i][k] across all 4 dot products:
   *
   *   Without blocking: 2 loads + 1 FMA per SIMD iteration
   *   With blocking x4:  5 loads + 4 FMAs per SIMD iteration
   *
   * This improves the load-to-FMA ratio from 2:1 to 5:4, yielding
   * ~33% higher throughput on load-port-limited microarchitectures.
   *
   * restrict qualifiers assert no aliasing between data_t rows,
   * enabling the compiler to fully auto-vectorize with AVX2/AVX-512.
   * All accumulators (s0-s3) live in registers throughout the k loop.
   * ================================================================= */

  for (i = 0; i < _PB_M - 1; i++)
  {
    corr[i][i] = SCALAR_VAL(1.0);

    /* Register-blocked path: 4 j values sharing data_t[i] loads */
    j = i + 1;
    for (; j + 3 < _PB_M; j += 4)
    {
      DATA_TYPE s0 = SCALAR_VAL(0.0);
      DATA_TYPE s1 = SCALAR_VAL(0.0);
      DATA_TYPE s2 = SCALAR_VAL(0.0);
      DATA_TYPE s3 = SCALAR_VAL(0.0);
      const DATA_TYPE * restrict di  = data_t[i];
      const DATA_TYPE * restrict dj0 = data_t[j];
      const DATA_TYPE * restrict dj1 = data_t[j + 1];
      const DATA_TYPE * restrict dj2 = data_t[j + 2];
      const DATA_TYPE * restrict dj3 = data_t[j + 3];
      for (k = 0; k < _PB_N; k++) {
        DATA_TYPE d = di[k];
        s0 += d * dj0[k];
        s1 += d * dj1[k];
        s2 += d * dj2[k];
        s3 += d * dj3[k];
      }
      corr[i][j]     = s0; corr[j][i]     = s0;
      corr[i][j + 1] = s1; corr[j + 1][i] = s1;
      corr[i][j + 2] = s2; corr[j + 2][i] = s2;
      corr[i][j + 3] = s3; corr[j + 3][i] = s3;
    }

    /* Scalar remainder: handle last 0-3 j values */
    for (; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      const DATA_TYPE * restrict di = data_t[i];
      const DATA_TYPE * restrict dj = data_t[j];
      for (k = 0; k < _PB_N; k++)
        sum += di[k] * dj[k];
      corr[i][j] = sum;
      corr[j][i] = sum;
    }
  }
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);

  free(data_t);

#pragma endscop

}


